(5596678, 809364, 15711, '<td valign="top">Great shot, MAK.  I had no idea it was yours.</td>', 'Great shot, MAK.  I had no idea it was yours.', '2009-08-03 09:17:21.000000', NULL, 0),
(5596679, 809154, 38478, '<td valign="top">Often I enter challenges, not so much hoping for a good score as wondering what others will think and say about my entry. I apologize for not commenting during voting, it gets overwhelming sometimes. But seeing as this was one of the best images in the challenge, and one of my 8s, but got no comments, I''ll give you my impression. <br/> <br/>This is a wonderfully composed image, with excellent technicals as well. I admire how you were able to keep the whites intact, but not make the entire image too dark. The way the tree on the right framed and balanced the diagonals of the other trees is also very nice. Thank you.</td>', 'Often I enter challenges, not so much hoping for a good score as wondering what others will think and say about my entry. I apologize for not commenting during voting, it gets overwhelming sometimes. But seeing as this was one of the best images in the challenge, and one of my 8s, but got no comments, I''ll give you my impression.  This is a wonderfully composed image, with excellent technicals as well. I admire how you were able to keep the whites intact, but not make the entire image too dark. The way the tree on the right framed and balanced the diagonals of the other trees is also very nice. Thank you.', '2009-08-03 09:17:37.000000', NULL, 0),
(5596680, 808936, 15711, '<td valign="top">I think this is really artful and met the challenge perfectly.</td>', 'I think this is really artful and met the challenge perfectly.', '2009-08-03 09:17:51.000000', NULL, 0),
