INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5655858, 809786, 67027, '<td valign="top">Was just looking through my favourites again - it soothes my soul :-) and came upon this again.<br/> <br/>I still absolutely adore it, the reflection, the joy in his movement, his almost in focus face.<br/> <br/>It''s charming.</td>', 'Was just looking through my favourites again - it soothes my soul :-) and came upon this again. I still absolutely adore it, the reflection, the joy in his movement, his almost in focus face. It''s charming.', '2009-09-21 13:35:31.000000', NULL, 0),
(5705023, 809787, 67145, '<td valign="top">she''s adorable and amazingly photogenic .. how excellent to be a photographer and have this gorgeous little girl to photograph whenever you like .. you must have tons of wonderful pics of her .. this image is stupendous .. i love your imaginative approach and excellent technical expertise .. its a perfect image in every way and perfect for the challenge ..:)</td>', 'she''s adorable and amazingly photogenic .. how excellent to be a photographer and have this gorgeous little girl to photograph whenever you like .. you must have tons of wonderful pics of her .. this image is stupendous .. i love your imaginative approach and excellent technical expertise .. its a perfect image in every way and perfect for the challenge ..:)', '2009-10-29 01:12:50.000000', NULL, 0),
(5707681, 809528, 29748, '<td valign="top">Beautiful</td>', 'Beautiful', '2009-10-31 21:41:20.000000', NULL, 0),
(5711912, 809589, 72268, '<td valign="top">I love this photo, I think you did an amazing job.</td>', 'I love this photo, I think you did an amazing job.', '2009-11-03 09:02:06.000000', NULL, 0),
(5714860, 809621, 90495, '<td valign="top">I hadn''t seen this until now. So beautiful, <b>I</b> want to move there too. Your subtle enhancements are very powerful in bringing out the soft highlights needed for balance in tonality because of the mist. Superb.</td>', 'I hadn''t seen this until now. So beautiful, I want to move there too. Your subtle enhancements are very powerful in bringing out the soft highlights needed for balance in tonality because of the mist. Superb.', '2009-11-04 23:40:41.000000', NULL, 0),
(5722855, 809774, 69008, '<td valign="top">Wow! You must have either been very lucky to be prepared to get this shot, or you saw it coming and had enough time to raise your camera. <br/>It fit the challenge perfectly with the username association.</td>', 'Wow! You must have either been very lucky to be prepared to get this shot, or you saw it coming and had enough time to raise your camera. It fit the challenge perfectly with the username association.', '2009-11-11 07:08:43.000000', NULL, 0),
(5745560, 809734, 23484, '<td valign="top">Nice. I like the leading lines of the narrow alley.</td>', 'Nice. I like the leading lines of the narrow alley.', '2009-11-29 13:19:36.000000', NULL, 0),
(5771509, 809065, 83845, '<td valign="top">Amazing shot!</td>', 'Amazing shot!', '2009-12-18 14:32:39.000000', NULL, 0),
(5771604, 808919, 103142, '<td valign="top">Just came across this again -- it is so incredibly wonderful!!</td>', 'Just came across this again -- it is so incredibly wonderful!!', '2009-12-18 17:06:15.000000', NULL, 0),
(5901871, 808844, 30982, '<td valign="top">See, now the watermark on this one doesn''t bother me.  Almost looks like a commercial magazine kinda thing with a short caption on the photo.  Doesn''t detract from the flow or the mood of it at all.</td>', 'See, now the watermark on this one doesn''t bother me.  Almost looks like a commercial magazine kinda thing with a short caption on the photo.  Doesn''t detract from the flow or the mood of it at all.', '2010-03-12 20:57:44.000000', NULL, 0),
(6072503, 809065, 103142, '<td valign="top">This is a really cool shot! I love the non-existent background (but I''m partial to that, even though some people really don''t like it.) I''d actually be tempted to clone out the petals of the flower and just leave the stamen.</td>', 'This is a really cool shot! I love the non-existent background (but I''m partial to that, even though some people really don''t like it.) I''d actually be tempted to clone out the petals of the flower and just leave the stamen.', '2010-06-28 20:01:20.000000', NULL, 0),
(6080406, 809065, 37845, '<td valign="top">Very nice take on the bug macro. The partially desaturated, high key processing in this shot separate this one from other bug macros. I think the score doesnt do this photo justice.</td>', 'Very nice take on the bug macro. The partially desaturated, high key processing in this shot separate this one from other bug macros. I think the score doesnt do this photo justice.', '2010-07-05 01:23:51.000000', NULL, 0),
(6094541, 809621, 119485, '<td valign="top">it''s beautiful</td>', 'it''s beautiful', '2010-07-15 22:19:00.000000', NULL, 0),
(6114671, 808856, 58785, '<td valign="top">Very nice photo. Again, excellent job with Sepia work. Your face compositions are excellent. One the major points that I would like to master also</td>', 'Very nice photo. Again, excellent job with Sepia work. Your face compositions are excellent. One the major points that I would like to master also', '2010-08-03 01:54:55.000000', NULL, 0),
